function SuccessMessage() {
  return (
    <div className="flex w-full flex-col items-center gap-5 px-6 pb-6 pt-8">
      <SuccessIllustration />
      <div className="flex w-full flex-col items-center gap-2 text-center">
        <p className="text-heading-h4 font-bold text-warm-neutral-900">방명록이 저장되었어요!</p>
        <p className="text-body-sm text-cool-neutral-500">소중한 제주 여행의 추억이 기록되었습니다.</p>
      </div>
    </div>
  );
}

function PreviewCard() {
  return (
    <div className="w-full px-8">
      <div className="flex w-full flex-col gap-4 rounded-xl bg-cool-neutral-white p-4 shadow-[0_12px_24px_rgba(0,0,0,0.06)]">
        {/* TODO: 실제 이미지/에셋 교체 */}
        <div className="h-[198px] w-full rounded-md bg-cool-neutral-200" />
        <div className="flex w-full flex-col gap-2.5">
          <div className="flex w-full items-center justify-between">
            <span className="text-body-sm text-cool-neutral-400">{mock.visitedDate}</span>
            <span className="text-body-sm text-cool-neutral-400">{mock.weather}</span>
          </div>
          <p className="text-body-md text-cool-neutral-800">{mock.description}</p>
          <div className="flex items-center gap-1">
            <IconMapPin className="h-3.5 w-3.5 shrink-0" fill="#77be36" />
            <span className="text-label-sm font-medium text-tertiary-600">{mock.placeName}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

function SelectFields() {
  return (
    <div className="flex w-full flex-col gap-3 px-8">
      <div className="flex w-full flex-col gap-2">
        <span className="text-label-sm font-medium text-warm-neutral-900">다녀온 장소</span>
        <button
          type="button"
          className="flex w-full items-center gap-2.5 rounded-lg border border-warm-neutral-100 bg-cool-neutral-white p-3"
        >
          <IconMapPin className="h-3.5 w-3.5 shrink-0" fill="#82c34a" />
          <span className="flex-1 text-left text-body-md text-cool-neutral-500">장소를 검색해 보세요</span>
        </button>
      </div>
      <div className="flex w-full flex-col gap-2">
        <span className="text-label-sm font-medium text-warm-neutral-900">방문한 날짜</span>
        <button
          type="button"
          className="flex h-12 w-full shrink-0 items-center justify-between rounded-lg border border-warm-neutral-100 bg-cool-neutral-white px-4"
        >
          <span className="text-body-md text-cool-neutral-500">날짜를 선택해주세요</span>
          <IconCalendar />
        </button>
      </div>
    </div>
  );
}

function BottomActions() {
  return (
    <div className="w-full px-4 pb-7 pt-3">
      <button
        type="button"
        className="text-label-lg flex h-13 w-full items-center justify-center rounded-full bg-cool-neutral-800 px-6 py-3.5 font-medium text-cool-neutral-white"
      >
        홈으로 이동하기
      </button>
    </div>
  );
}

export default function TravelSaveCompleteScreen() {
  return (
    <div className="flex min-h-screen w-full flex-col items-center bg-gradient-to-b from-tertiary-50 to-tertiary-100">
      <SuccessMessage />
      <PreviewCard />
      <SelectFields />
      <BottomActions />
    </div>
  );
}
